return ['project-id-version'=>'Disable All WordPress Updates','report-msgid-bugs-to'=>'','pot-creation-date'=>'2021-11-11 15:32+0000','po-revision-date'=>'2026-08-09 12:52+0000','last-translator'=>'','language-team'=>'Deutsch','language'=>'de_DE','plural-forms'=>'nplurals=2; plural=n != 1;','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','x-generator'=>'Loco https://localise.biz/','x-loco-version'=>'2.5.3; wp-5.8','x-domain'=>'disable-wordpress-updates','messages'=>['"%s" plugin is enabled! Click to manage update settings.'=>'Das „%s“-Plugin ist aktiviert! Klicke hier, um die Update-Einstellungen zu verwalten.','all core updates'=>'alle Core-Updates','Disable All WordPress Updates'=>'Disable All WordPress Updates','Disable Updates'=>'Updates deaktivieren','Disables the theme, plugin and core update checking, the related cronjobs and notification system.'=>'Deaktiviert die Theme-, Plugin- und Core-Updates, die zugehörigen Cronjobs und das Benachrichtigungssystem.','Enable security updates only (block major updates)'=>'Nur Sicherheitsupdates zulassen (größere Updates blockieren)','https://wordpress.org/plugins/disable-wordpress-updates/'=>'https://de.wordpress.org/plugins/disable-wordpress-updates/','https://www.schloebe.de/'=>'https://www.schloebe.de/','Implemented with WordPress filters only — no wp-config.php edits. Plugin and theme auto-updates are not affected by this setting.'=>'Wird ausschließlich über WordPress-Filter umgesetzt – keine Änderungen an der wp-config.php. Automatische Updates für Plugins und Themes sind von dieser Einstellung nicht betroffen.','minor / security only'=>'nur kleine und Sicherheitsupdates','no core updates'=>'keine Core-Updates','Note: this setting controls which core releases are eligible for automatic updates. If the automatic updater is disabled site-wide (for example via the AUTOMATIC_UPDATER_DISABLED constant/filter, or by this plugin\'s own update-blocking features), that takes precedence and no core update will be applied automatically regardless of this toggle.'=>'Hinweis: Diese Einstellung legt fest, welche Core-Versionen für automatische Updates in Frage kommen. Wenn der automatische Updater seitenweit deaktiviert ist (zum Beispiel über die Konstante/den Filter `AUTOMATIC_UPDATER_DISABLED` oder durch die eigenen Funktionen dieses Plugins zum Blockieren von Updates), hat das Vorrang und es wird unabhängig von dieser Umschaltfunktion kein Core-Update automatisch angewendet.','Oliver Schlöbe'=>'Oliver Schlöbe','Security Mode'=>'Sicherheitsmodus','Security Mode enabled.'=>'Sicherheitsmodus aktiviert.','Security Mode is enabled: WordPress core automatic updates are restricted to minor and security releases. Major version updates are intentionally blocked.'=>'Der Sicherheitsmodus ist aktiviert: Automatische Updates des WordPress-Cores sind auf Neben- und Sicherheitsupdates beschränkt. Updates auf neue Hauptversionen werden bewusst blockiert.','Security Mode restricts WordPress core automatic updates to minor and security releases. Major version and development (nightly) core updates are blocked from being applied automatically.'=>'Der Sicherheitsmodus beschränkt die automatischen Updates des WordPress-Cores auf Nebenversionen und Sicherheitsupdates. Die automatische Installation von Hauptversions- und Entwicklungs-Updates (Nightly-Updates) des Cores wird blockiert.','Status'=>'Status','The %s constant is defined outside of this plugin (for example in wp-config.php, a host panel, an mu-plugin or another plugin) with the following value:'=>'Die Konstante %s wird außerhalb dieses Plugins (zum Beispiel in wp-config.php, einem Host-Panel, einem mu-Plugin oder einem anderen Plugin) mit dem folgenden Wert definiert:','This constant always overrides this plugin\'s filters, so the Security Mode toggle may have no effect. To rely on Security Mode, remove or adjust that constant definition.'=>'Diese Konstante hat immer Vorrang vor den Filtern dieses Plugins, sodass der Schalter für den Sicherheitsmodus möglicherweise keine Wirkung zeigt. Wenn du dich auf den Sicherheitsmodus verlassen möchtest, entferne oder passe die Definition dieser Konstante an.','WP_AUTO_UPDATE_CORE is defined elsewhere'=>'WP_AUTO_UPDATE_CORE ist an anderer Stelle definiert']];
